import { ViewType, ProductionScreenType } from '../types';

// Explicações pra cada data-guide-anchor já existente (ver GuidedTourOverlay.tsx e
// journeys.ts) — consumido pelo "?" arrastável (DraggableHelpPoint.tsx). Dado puro, sem
// lógica: soltar o "?" perto de um anchor mostra este texto num popup; anchors compartilhados
// por dois contextos (ex.: people.novo serve Cliente e Fornecedor) recebem um texto genérico
// que cobre os dois, em vez de tentar adivinhar em qual dos dois a pessoa está.

export type FieldHelpEntry = {
  text: string;
  relatedView?: ViewType;
  relatedParams?: any;
  relatedLabel?: string;
  // Só relevante quando relatedView é PRODUCTION_CONFIG — abre direto na aba certa (mesmo
  // mecanismo já usado pelos tours/onboarding, ver App.tsx setProductionSubScreen).
  relatedProductionSubScreen?: ProductionScreenType;
};

